BOOL WINAPI SetupDiGetDeviceRegistryPropertyA(HDEVINFO devinfo,
        SP_DEVINFO_DATA *device_data, DWORD Property, DWORD *PropertyRegDataType,
        BYTE *PropertyBuffer, DWORD PropertyBufferSize, DWORD *RequiredSize)
{
    BOOL ret = FALSE;
    struct device *device;

    TRACE("devinfo %p, device_data %p, property %ld, type %p, buffer %p, size %ld, required %p\n",
            devinfo, device_data, Property, PropertyRegDataType, PropertyBuffer, PropertyBufferSize, RequiredSize);

    if (!(device = get_device(devinfo, device_data)))
        return FALSE;

    if (PropertyBufferSize && PropertyBuffer == NULL)
    {
        SetLastError(ERROR_INVALID_DATA);
        return FALSE;
    }

    if (Property == SPDRP_ENUMERATOR_NAME)
    {
        const WCHAR *backslash;
        DWORD len;
        int size_needed, size_written;

        if (!device->instanceId || !*device->instanceId)
        {
            SetLastError(ERROR_INVALID_DATA);
            return FALSE;
        }

        backslash = wcschr(device->instanceId, L'\\');
        len = backslash ? (DWORD)(backslash - device->instanceId) : lstrlenW(device->instanceId);
        if (len == 0)
        {
            SetLastError(ERROR_INVALID_DATA);
            return FALSE;
        }

        size_needed = WideCharToMultiByte(CP_ACP, 0, device->instanceId, len, NULL, 0, NULL, NULL);
        if (size_needed <= 0)
        {
            SetLastError(ERROR_INVALID_DATA);
            return FALSE;
        }

        size_needed++;

        if (RequiredSize)
            *RequiredSize = size_needed;

        if (PropertyRegDataType)
            *PropertyRegDataType = REG_SZ;

        if (!PropertyBuffer || (int)PropertyBufferSize < size_needed)
        {
            SetLastError(ERROR_INSUFFICIENT_BUFFER);
            return FALSE;
        }

        size_written = WideCharToMultiByte(CP_ACP, 0,
                                           device->instanceId, len,
                                           (char *)PropertyBuffer,
                                           PropertyBufferSize - 1,
                                           NULL, NULL);

        if (size_written <= 0)
        {
            SetLastError(ERROR_INVALID_DATA);
            return FALSE;
        }

        ((char *)PropertyBuffer)[size_written] = 0;
        return TRUE;
    }

    if (Property < ARRAY_SIZE(PropertyMap) && PropertyMap[Property].nameA)
    {
        DWORD size = PropertyBufferSize;
        LONG l = RegQueryValueExA(device->key, PropertyMap[Property].nameA,
                NULL, PropertyRegDataType, PropertyBuffer, &size);

        if (l == ERROR_FILE_NOT_FOUND)
            SetLastError(ERROR_INVALID_DATA);
        else if (l == ERROR_MORE_DATA || !PropertyBufferSize)
            SetLastError(ERROR_INSUFFICIENT_BUFFER);
        else if (!l)
            ret = TRUE;
        else
            SetLastError(l);
        if (RequiredSize)
            *RequiredSize = size;
    }
    else
    {
        SetLastError(ERROR_INVALID_DATA);
    }
    return ret;
}

